function validate(input) {
  const [fn, inputs, t] = input;
  if (!Number.isInteger(t) || t < 0 || t > 1000) return 't must be an integer from 0 to 1000.';
  if (!Array.isArray(inputs) || inputs.length > 10 || !inputs.every((x) => Number.isInteger(x) && x >= -1000 && x <= 1000)) return 'inputs must be at most 10 integers from -1000 to 1000.';
  if (!fn || typeof fn !== 'object' || Array.isArray(fn)) return 'fn must be an object such as { "t": 100, "compute": "square" }.';
  if (!Number.isInteger(fn.t) || fn.t < 0 || fn.t > 1000) return 'fn.t must be an integer from 0 to 1000.';
  const keys = Object.keys(fn).sort().join(',');
  if (keys === 't,throws') {
    if (typeof fn.throws !== 'string' || fn.throws.length < 1 || fn.throws.length > 30) return 'fn.throws must be a string of 1 to 30 characters.';
  } else if (keys === 'compute,t') {
    if (fn.compute !== 'square' && fn.compute !== 'sum') return 'fn.compute must be "square" or "sum".';
    if (fn.compute === 'square' && inputs.length === 0) return '"square" needs at least one input.';
  } else return 'fn must have t and exactly one of compute or throws.';
  if (fn.t > 0 && fn.t === t) return 'Pick an fn.t different from t, so the result does not depend on a tie.';
  return null;
}

