function adapt(input, solve, kit) {
  const [spec, inputs, t] = input;
  const fn = async (...args) => {
    kit.trace(`fn(${args.join(', ')}) starts`);
    if (spec.t > 0) await new Promise((resolve) => setTimeout(resolve, spec.t));
    if (spec.throws !== undefined) {
      kit.trace(`fn rejects with "${spec.throws}"`);
      throw spec.throws;
    }
    const value = spec.compute === 'square' ? args[0] * args[0] : args.reduce((sum, x) => sum + x, 0);
    kit.trace(`fn resolves with ${value}`);
    return value;
  };
  const limited = solve(fn, t);
  if (typeof limited !== 'function') throw new Error('timeLimit must return a function.');
  const start = Date.now();
  kit.trace(`limited(${inputs.join(', ')}) is called with a limit of ${t} ms`);
  const promise = limited(...inputs);
  if (!promise || typeof promise.then !== 'function') throw new Error('The limited function must return a promise.');
  return promise.then((value) => {
    const time = Date.now() - start;
    kit.trace(`The limited promise resolves with ${JSON.stringify(value)}`);
    return { resolved: value, time };
  }, (error) => {
    const time = Date.now() - start;
    const rejected = error instanceof Error ? String(error) : error;
    kit.trace(`The limited promise rejects with ${JSON.stringify(rejected)}`);
    return { rejected, time };
  });
}

