function generate(rand, size) {
  const pick = (max) => Math.floor(rand() * (max + 1));
  const range = size === 'small' ? 200 : 1000;
  const t = rand() < 0.1 ? 0 : pick(range);
  let delay = rand() < 0.15 ? 0 : pick(range);
  if (delay > 0 && delay === t) delay = t - 1;
  const count = size === 'small' ? pick(4) : 5 + pick(5);
  const spread = size === 'small' ? 20 : 1000;
  const inputs = Array.from({ length: count }, () => pick(2 * spread) - spread);
  const roll = rand();
  let fn;
  if (roll < 0.25) fn = { t: delay, throws: ['Error', 'Bad input', 'Network down'][pick(2)] };
  else if (roll < 0.6 && count > 0) fn = { t: delay, compute: 'square' };
  else fn = { t: delay, compute: 'sum' };
  return [fn, inputs, t];
}
